all_files = {}
for root, dirs, files in os.walk(wiki_dir):
    if 'templates' in root.split(os.sep):
        continue
    for f in files:
        if f.endswith('.md'):
            rel = os.path.relpath(os.path.join(root, f), wiki_dir)
            rel = rel.replace(os.sep, '/')
            all_files[rel] = []

# For each file, find all incoming wiki links
for root, dirs, files in os.walk(wiki_dir):
    for f in files:
        if not f.endswith('.md'):
            continue
        fp = os.path.join(root, f)
        rel = os.path.relpath(fp, wiki_dir).replace(os.sep, '/')
        with open(fp, 'r', encoding='utf-8') as fh:
            content = fh.read()
        for m in re.finditer(r'\[\[wiki/([^\]]+?)(?:\|[^\]]+)?\]\]', content):
            target_raw = m.group(1)
            target_file = target_raw + '.md' if not target_raw.endswith('.md') else target_raw
            if target_file in all_files and target_file != rel:
                all_files[target_file].append(rel)

special = {'index.md', 'log.md', 'tag-index.md'}
orphans = []
for f, incoming in sorted(all_files.items()):
    if f in special:
        continue
    if not incoming:
        orphans.append(f)

if orphans:
    print('PAGES WITH NO INCOMING WIKI LINKS:')
    for o in orphans:
        print(' ', o)
else:
    print('ALL PAGES HAVE INCOMING LINKS.')
